import{_ as t,a as s,c as r,ac as a}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Docker 知识库","description":"Docker 学习路径与操作专题总览","frontmatter":{"title":"Docker 知识库","description":"从容器基础到生产运维的 Docker 中文分章教程与命令手册","sources":[{"repository":"TeamDocs","file":"docs/engineering/docker/index.md"}],"showdocs":{"topics":[{"id":"docker","title":"Docker","link":"/topics/docker/"}],"kind":"故障排查","scope":"general","audience":"general","group":"容器与运维","summary":"Docker 学习路径与操作专题总览","status":"active","related":[{"title":"BuildKit 与 Buildx","link":"/systems/docker/plus/subjects/08-buildkit-and-buildx","kind":"知识专题","scope":"general","audience":"general"},{"title":"Docker 操作与命令","link":"/systems/docker/plus/ecosystem/docker-general-general","kind":"命令","scope":"general","audience":"general"},{"title":"Docker 常用命令与对象速查","link":"/systems/docker/commands","kind":"命令","scope":"general","audience":"general"},{"title":"Docker 存储","link":"/systems/docker/plus/subjects/06-storage","kind":"知识专题","scope":"general","audience":"general"},{"title":"Docker 镜像管理","link":"/systems/docker/plus/subjects/03-images","kind":"知识专题","scope":"general","audience":"general"}],"prev":false,"next":false},"prev":false,"next":false},"headers":[],"relativePath":"systems/docker/overview.md","filePath":"systems/docker/overview.md"}'),o={name:"systems/docker/overview.md"};function d(i,e,l,c,n,u){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="docker-知识库" tabindex="-1">Docker 知识库 <a class="header-anchor" href="#docker-知识库" aria-label="Permalink to &quot;Docker 知识库&quot;">​</a></h1><blockquote><p>面向开发、测试和运维人员的 Docker 系统教程。版本信息核对日期：<strong>2026-08-12</strong>。</p></blockquote><h2 id="_1-阅读说明" tabindex="-1">1. 阅读说明 <a class="header-anchor" href="#_1-阅读说明" aria-label="Permalink to &quot;1. 阅读说明&quot;">​</a></h2><p>本知识库同时覆盖“为什么”“怎么做”和“出问题怎么办”。所有命令默认在 Linux Shell 中执行；示例名称、端口、路径和镜像仓库地址应按实际环境替换。</p><p>文档中的提示分为三类：</p><ul><li><strong>提示</strong>：推荐做法或容易忽略的行为。</li><li><strong>警告</strong>：可能中断服务、暴露端口或改变数据。</li><li><strong>危险</strong>：可能删除镜像、容器、卷或宿主机文件；执行前必须确认目标并完成备份。</li></ul><p>Docker 命令通常要求访问 Docker daemon。加入 <code>docker</code> 用户组等价于授予接近宿主机 root 的权限，不应把它当作普通的免 <code>sudo</code> 便利设置。生产环境优先使用最小授权、Rootless 模式或受控的远程上下文。</p><h2 id="_2-推荐学习路线" tabindex="-1">2. 推荐学习路线 <a class="header-anchor" href="#_2-推荐学习路线" aria-label="Permalink to &quot;2. 推荐学习路线&quot;">​</a></h2><h3 id="_2-1-初学者" tabindex="-1">2.1 初学者 <a class="header-anchor" href="#_2-1-初学者" aria-label="Permalink to &quot;2.1 初学者&quot;">​</a></h3><ol><li><a href="/systems/docker/plus/subjects/01-version-and-architecture">版本与架构</a></li><li><a href="/systems/docker/base/basic/02-installation-and-configuration">安装与基础配置</a></li><li><a href="/systems/docker/plus/subjects/03-images">镜像管理</a></li><li><a href="/systems/docker/plus/subjects/04-containers">容器生命周期</a></li><li><a href="/systems/docker/plus/subjects/05-networking">网络</a></li><li><a href="/systems/docker/plus/subjects/06-storage">存储</a></li><li><a href="/systems/docker/plus/subjects/07-dockerfile">Dockerfile</a></li><li><a href="/systems/docker/plus/subjects/09-compose">Compose</a></li></ol><h3 id="_2-2-进阶开发者" tabindex="-1">2.2 进阶开发者 <a class="header-anchor" href="#_2-2-进阶开发者" aria-label="Permalink to &quot;2.2 进阶开发者&quot;">​</a></h3><ol><li><a href="/systems/docker/plus/subjects/08-buildkit-and-buildx">BuildKit 与 Buildx</a></li><li><a href="/systems/docker/plus/subjects/10-registry">Registry 与镜像分发</a></li><li><a href="/systems/docker/plus/subjects/11-resource-management">资源限制与性能</a></li><li><a href="/systems/docker/plus/subjects/12-security">安全</a></li><li><a href="/systems/docker/plus/subjects/13-logging-and-monitoring">日志与监控</a></li></ol><h3 id="_2-3-运维与生产负责人" tabindex="-1">2.3 运维与生产负责人 <a class="header-anchor" href="#_2-3-运维与生产负责人" aria-label="Permalink to &quot;2.3 运维与生产负责人&quot;">​</a></h3><ol><li><a href="/systems/docker/plus/troubleshooting/14-troubleshooting">故障排查</a></li><li><a href="/systems/docker/plus/practice/15-maintenance-backup-and-upgrade">维护、清理、备份与升级</a></li><li><a href="/systems/docker/plus/practice/16-ci-cd-and-production">CI/CD 与生产实践</a></li><li><a href="/systems/docker/plus/ecosystem/17-command-reference">命令速查</a></li></ol><h2 id="_3-章节导航" tabindex="-1">3. 章节导航 <a class="header-anchor" href="#_3-章节导航" aria-label="Permalink to &quot;3. 章节导航&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>内容</th><th>适合场景</th></tr></thead><tbody><tr><td><a href="/systems/docker/plus/subjects/01-version-and-architecture">01 版本与架构</a></td><td>最新稳定版本、组件关系、OCI、隔离原理</td><td>建立整体认知、规划升级</td></tr><tr><td><a href="/systems/docker/base/basic/02-installation-and-configuration">02 安装与配置</a></td><td>Ubuntu 安装、daemon、Context、Rootless</td><td>新机器初始化</td></tr><tr><td><a href="/systems/docker/plus/subjects/03-images">03 镜像</a></td><td>拉取、标签、摘要、导入导出、检查</td><td>管理构建产物</td></tr><tr><td><a href="/systems/docker/plus/subjects/04-containers">04 容器</a></td><td>创建、启动、进入、复制、更新、健康检查</td><td>日常开发与运维</td></tr><tr><td><a href="/systems/docker/plus/subjects/05-networking">05 网络</a></td><td>bridge、DNS、端口、IPv6、排查</td><td>服务互通与暴露</td></tr><tr><td><a href="/systems/docker/plus/subjects/06-storage">06 存储</a></td><td>volume、bind、tmpfs、权限、备份</td><td>持久化数据</td></tr><tr><td><a href="/systems/docker/plus/subjects/07-dockerfile">07 Dockerfile</a></td><td>指令、缓存、多阶段、非 root、最佳实践</td><td>编写可维护镜像</td></tr><tr><td><a href="/systems/docker/plus/subjects/08-buildkit-and-buildx">08 BuildKit/Buildx</a></td><td>Builder、缓存、多平台、Secret、SBOM</td><td>高级构建与供应链</td></tr><tr><td><a href="/systems/docker/plus/subjects/09-compose">09 Compose</a></td><td>多服务编排、环境变量、profile、扩缩容</td><td>本地或单机应用栈</td></tr><tr><td><a href="/systems/docker/plus/subjects/10-registry">10 Registry</a></td><td>登录、推送、私库、镜像提升、不可变标签</td><td>镜像分发</td></tr><tr><td><a href="/systems/docker/plus/subjects/11-resource-management">11 资源与性能</a></td><td>CPU、内存、PID、I/O、ulimit</td><td>防止资源争抢</td></tr><tr><td><a href="/systems/docker/plus/subjects/12-security">12 安全</a></td><td>权限、能力、seccomp、Secret、扫描</td><td>安全基线</td></tr><tr><td><a href="/systems/docker/plus/subjects/13-logging-and-monitoring">13 日志与监控</a></td><td>日志驱动、轮转、events、stats、指标</td><td>可观测性</td></tr><tr><td><a href="/systems/docker/plus/troubleshooting/14-troubleshooting">14 排障</a></td><td>分层诊断、常见错误、救援命令</td><td>故障定位</td></tr><tr><td><a href="/systems/docker/plus/practice/15-maintenance-backup-and-upgrade">15 维护与升级</a></td><td>安全清理、卷备份、升级回退</td><td>长期维护</td></tr><tr><td><a href="/systems/docker/plus/practice/16-ci-cd-and-production">16 CI/CD 与生产</a></td><td>构建发布、签名、部署清单、生产检查</td><td>交付上线</td></tr><tr><td><a href="/systems/docker/plus/ecosystem/17-command-reference">17 命令速查</a></td><td>高频命令、过滤、格式化、危险命令</td><td>值班速查</td></tr></tbody></table><h2 id="_4-先记住的五个原则" tabindex="-1">4. 先记住的五个原则 <a class="header-anchor" href="#_4-先记住的五个原则" aria-label="Permalink to &quot;4. 先记住的五个原则&quot;">​</a></h2><ol><li><strong>镜像不可变，数据外置。</strong> 应用版本进入镜像，业务数据进入卷或外部服务。</li><li><strong>按摘要部署。</strong> 标签可移动；生产发布记录应保留镜像 digest。</li><li><strong>容器不是虚拟机。</strong> 一个容器通常承载一个主要职责，并通过前台主进程维持生命周期。</li><li><strong>默认最小权限。</strong> 非 root 用户、只读根文件系统、删除多余 capabilities，不挂载 Docker socket。</li><li><strong>删除前先盘点。</strong> 先执行 <code>docker system df -v</code>、检查标签和卷，再使用 prune 类命令。</li></ol><h2 id="_5-官方资料" tabindex="-1">5. 官方资料 <a class="header-anchor" href="#_5-官方资料" aria-label="Permalink to &quot;5. 官方资料&quot;">​</a></h2><ul><li><a href="https://docs.docker.com/" target="_blank" rel="noopener noreferrer">Docker Docs</a></li><li><a href="https://docs.docker.com/reference/cli/docker/" target="_blank" rel="noopener noreferrer">Docker CLI Reference</a></li><li><a href="https://docs.docker.com/engine/release-notes/" target="_blank" rel="noopener noreferrer">Docker Engine Release Notes</a></li><li><a href="https://compose-spec.io/" target="_blank" rel="noopener noreferrer">Compose Specification</a></li><li><a href="https://opencontainers.org/" target="_blank" rel="noopener noreferrer">Open Container Initiative</a></li></ul><p>本知识库用于团队学习和操作参考。涉及升级、安全公告、废弃特性和平台支持范围时，以执行当日的官方文档为准。</p>',21)])])}const p=t(o,[["render",d]]);export{h as __pageData,p as default};
